struct Buttons
{
    int x;
    int y;
    int width;
    int height;
    string image;
    string text;
    string fillRule = "nonzero";
};

QIcon createIcon(QString path, QString fillRule = "nonzero")
{
    QString svg = R"(
        <svg xmlns="http://www.w3.org/2000/svg"
             width="84" height="84" viewBox="0 0 84 84">
            <path fill="white" fill-rule=")" + fillRule + R"(" d=")" + path + R"("/>
        </svg>
    )";

    QSvgRenderer renderer(svg.toUtf8());

    QPixmap pixmap(84, 84);
    pixmap.fill(Qt::transparent);

    QPainter painter(&pixmap);
    renderer.render(&painter);

    return QIcon(pixmap);
}

