int main(int argc, char *argv[]) {

    QApplication app(argc, argv);
    QMainWindow window;
    
    QPushButton *GoButton = new QPushButton("&GO", &window);
    GoButton->setGeometry(17, 17, 130, 82);
    GoButton->setStyleSheet("font-size:50px; background-color: #787583;");

    QLabel *StandbyDisplay = new QLabel("[no cue on standby]", &window);
    StandbyDisplay->setGeometry(165, 17, 1738, 31);
    StandbyDisplay->setStyleSheet("background-color: #3c3c3c; color: white; border-radius:4;padding-left: 5px; font-size:16px");
    StandbyDisplay->setAlignment(Qt::AlignVCenter);

    QLabel *NotesField = new QLabel("", &window);
    NotesField->setGeometry(164, 63, 1739, 37);
    NotesField->setStyleSheet("color: white; border-radius:2; padding-left: 5px; font-size:16px; border: 4px solid #3a3a3a;");
    NotesField->setAlignment(Qt::AlignVCenter);

    QVector<QPushButton*> Button;

    for (int i = 0; i < ButtonData.size(); i++) {
        Button.push_back(new QPushButton(&window));

        if (!ButtonData[i].image.empty()) {
            Button[i]->setIcon(createIcon(
                QString::fromStdString(ButtonData[i].image),
                QString::fromStdString(ButtonData[i].fillRule)
            ));
        }

        Button[i]->setGeometry(
            ButtonData[i].x,
            ButtonData[i].y,
            ButtonData[i].width,
            ButtonData[i].height
        );
    }

    window.setWindowState(Qt::WindowMaximized);
    window.setWindowTitle("QLabs");
    window.show();
    return app.exec();
}